          "Hoy mi abuelo Pau ha venido conmigo al observatorio del cerro. Soy Dani y quería enseñarle la cúpula. Nos hemos reunido con Mira y Joana, la guía adulta, al pie de la subida. Faltaban cuarenta minutos para la bienvenida en la sala. Pau miró los dos senderos y dijo que necesitaría sentarse durante el trayecto.",
          "Yo conocía un atajo casi recto. La última vez había llegado en quince minutos, sin parar. Joana explicó que no tenía bancos. El camino de las curvas requería unos veinticinco minutos caminando y tenía un banco a media subida. «La parada la contamos aparte», añadió. Pau prefirió ese camino: quería llegar con nosotros y poder descansar sentado antes.",
          "Al principio pensé que tardaríamos demasiado. Mira hizo la cuenta en voz baja: veinticinco minutos de camino y cinco de descanso serían treinta. Todavía quedarían diez antes de la bienvenida. Joana dijo que podíamos salir ya y ajustar la parada a lo que Pau necesitara. Si cambiaba el plan, ella avisaría a la persona que recibía al grupo arriba.",
          "Salimos juntos por las curvas. En el banco paramos los cuatro. El abuelo bebió agua y yo me senté a su lado. Desde allí la cúpula asomaba entre los pinos, aunque no se veía la puerta. «Una casa con sombrero», dije. Mira buscó con la mirada dónde le dibujaría una nariz. Pau señaló la chimenea de una casa lejana y nos reímos imaginando que llegaba hasta allí.",
          "Pau dijo que estaba listo al cabo de cinco minutos. Seguimos a su lado y la parte de camino que faltaba nos llevó hasta la entrada. La subida completa había durado treinta minutos, contando el descanso. La persona de recepción nos mostró dónde dejar las chaquetas: aún faltaban diez minutos para comenzar.",
          "Antes de entrar, el abuelo me preguntó si el banco seguiría allí a la vuelta. Le dije que propondría bajar por las curvas. Mira sacó la cantimplora para rellenarla en la sala. Yo dibujé en mi libreta una casa con un sombrero redondo y un banco a sus pies."
